class Csw2(object):
    ''' CSW 2.x server '''
    def __init__(self, server_csw):
        self.parent = server_csw
        self.version = '2.0.2'

    def getrecords(self):
        ''' Handle GetRecords request '''
        timestamp = util.get_today_and_now()

