        for param, desc in mandatory_params.items():
            if param not in self.parent.kvp:
                return self.exceptionreport('MissingParameterValue', param, f'Missing {desc} parameter(s)')

        self.parent.kvp['outputschema'] = self.parent.kvp.get('outputschema', self.parent.context.namespaces['csw'])
        if self.parent.kvp['outputschema'] not in self.parent.context.model['operations']['GetRecords']['parameters']['outputSchema']['values']:
            return self.exceptionreport('InvalidParameterValue', 'outputschema', f'Invalid outputSchema parameter value: {self.parent.kvp["outputschema"]}')

        self.parent.kvp['outputformat'] = self.parent.kvp.get('outputformat', 'application/xml')
        if self.parent.kvp['outputformat'] not in self.parent.context.model['operations']['GetRecords']['parameters']['outputFormat']['values']:
            return self.exceptionreport('InvalidParameterValue', 'outputformat', f'Invalid outputFormat parameter value: {self.parent.kvp["outputformat"]}')

        self.parent.kvp['resulttype'] = self.parent.kvp.get('resulttype', 'hits')
        if self.parent.kvp['resulttype'] and self.parent.kvp['resulttype'] not in self.parent.context.model['operations']['GetRecords']['parameters']['resultType']['values']:
            return self.exceptionreport('InvalidParameterValue', 'resulttype', f'Invalid resultType parameter value: {self.parent.kvp["resulttype"]}')

        if 'elementname' in self.parent.kvp:
            self.parent.kvp['elementname'] = self.parent.kvp['elementname'].split(',')
            self.parent.kvp['elementsetname'] = 'summary'

        self.parent.kvp['typenames'] = self.parent.kvp['typenames'].split(',')
        for tname in self.parent.kvp['typenames']:
            if tname not in self.parent.context.model['operations']['GetRecords']['parameters']['typeNames']['values']:
                return self.exceptionreport('InvalidParameterValue', 'typenames', f'Invalid typeNames parameter value: {tname}')

        for ename in self.parent.kvp.get('elementname', []):
            if ename not in self.parent.repository.queryables['_all'].keys():
                return self.exceptionreport('InvalidParameterValue', 'elementname', f'Invalid ElementName parameter value: {ename}')

        if self.parent.kvp['resulttype'] == 'validate':
            return self._write_acknowledgement()

        maxrecords_cfg = int(self.config.get('server', 'maxrecords', fallback=10))
        self.parent.kvp['maxrecords'] = int(self.parent.kvp.get('maxrecords', maxrecords_cfg))
        if self.parent.kvp['maxrecords'] > maxrecords_cfg:
            self.parent.kvp['maxrecords'] = maxrecords_cfg

        for param in ['bbox', 'q', 'time']:
            if param in self.parent.kvp:
                LOGGER.debug(f'OpenSearch {param.capitalize()} parameter detected.')
                self.parent.kvp['constraintlanguage'] = 'FILTER'
                tmp_filter = opensearch.kvp2filterxml(self.parent.kvp, self.parent.context)
                if tmp_filter:
                    self.parent.kvp['constraint'] = tmp_filter
                    LOGGER.debug('OpenSearch Geo/Time parameters to Filter: %s.', self.parent.kvp['constraint'])

        if 'constraint' in self.parent.kvp:
            if self.parent.kvp['constraintlanguage'] not in self.parent.context.model['operations']['GetRecords']['parameters']['CONSTRAINTLANGUAGE']['values']:
                return self.exceptionreport('InvalidParameterValue', 'constraintlanguage', f'Invalid constraintlanguage: {self.parent.kvp["constraintlanguage"]}')
            if self.parent.kvp['constraintlanguage'] == 'CQL_TEXT':
                try:
                    LOGGER.debug('Transforming CQL into fes1')
                    cql = cql2fes1(self.parent.kvp['constraint'], self.parent.context.namespaces)
                    self.parent.kvp['constraint'] = {'type': 'filter', 'where': None, 'values': None}
                    self.parent.kvp['constraint']['where'], self.parent.kvp['constraint']['values'] = fes1.parse(cql,
                                                                                                          self.parent.repository.queryables['_all'],
                                                                                                          self.parent.repository.dbtype,
                                                                                                          self.parent.context.namespaces,
                                                                                                          self.parent.orm,
                                                                                                          self.parent.language['text'],
                                                                                                          self.parent.repository.fts)
                except Exception as err:
                    LOGGER.error('Invalid CQL query %s', self.parent.kvp['constraint'])
                    LOGGER.error('Error message: %s', err, exc_info=True)
                    return self.exceptionreport('InvalidParameterValue', 'constraint', f'Invalid Filter syntax')

        if 'sortby' in self.parent.kvp:
            try:
                propname, order = self.parent.kvp['sortby'].rsplit(':', 1)
                self.parent.kvp['sortby'] = {
                    'propertyname': self.parent.repository.queryables['_all'][propname]['dbcol'],
                    'spatial': 'BoundingBox' in propname or 'Envelope' in propname,
                    'order': 'DESC' if order == 'D' else 'ASC'
                }
            except Exception as err:
                return self.exceptionreport('InvalidParameterValue', 'sortby', f'Invalid SortBy value: must be in the format propertyname:A or propertyname:D')

        startposition = int(self.parent.kvp.get('startposition', 1))
        LOGGER.debug('Querying repository with constraint: %s, sortby: %s, typenames: %s, maxrecords: %d, startposition: %d',
                    self.parent.kvp['constraint'], self.parent.kvp['sortby'], self.parent.kvp['typenames'], self.parent.kvp['maxrecords'], startposition)

        matched, results = self.parent.repository.query(
            constraint=self.parent.kvp['constraint'],
            sortby=self.parent.kvp['sortby'],
            typenames=self.parent.kvp['typenames'],
            maxrecords=self.parent.kvp['maxrecords'],
            startposition=startposition - 1)

        dsresults = []
        if self.config.has_option('server', 'federatedcatalogues') and self.kvp.get('distributedsearch', False) and self.kvp['hopcount'] > 0:
            LOGGER.debug('DistributedSearch specified (hopCount: %s).', self.kvp['hopcount'])
            from owslib.csw import CatalogueServiceWeb
            for fedcat in self.config.get('server', 'federatedcatalogues').split(','):
                LOGGER.debug('Performing distributed search on federated catalogue: %s.', fedcat)
                remotecsw = CatalogueServiceWeb(fedcat, skip_caps=True)
                try:
                    remotecsw.getrecords2(xml=self.parent.request,
                                          esn=self.kvp['elementsetname'],
                                          outputschema=self.kvp['outputschema'])
                    if hasattr(remotecsw, 'results'):
                        LOGGER.debug('Distributed search results from catalogue %s: %s.', fedcat, remotecsw.results)
                        dsresults.append(etree.Comment(f' {remotecsw.results["matches"]} results from {fedcat} '))
                        dsresults.append(remotecsw.records)
                except Exception as err:
                    error_string = f'remote CSW {fedcat} returned error: {err}'
                    dsresults.append(etree.Comment(f'{error_string}\n\n'))
                    LOGGER.error(error_string, exc_info=True)

        if not results:
            matched, returned, nextrecord = '0', '0', '0'
        else:
            returned = min(str(matched), str(self.parent.kvp['maxrecords']))
            nextrecord = '0' if int(matched) < int(self.parent.kvp['maxrecords']) else str(startposition + self.parent.kvp['maxrecords'])

        LOGGER.debug('Results: matched: %s, returned: %s, next: %s.', matched, returned, nextrecord)

        node = etree.Element('csw:GetRecordsResponse',
                             nsmap=self.parent.context.namespaces,
                             version='2.0.2')

        node.attrib[f'{{{self.parent.context.namespaces["xsi"]}}}schemaLocation'] = f'{self.parent.context.namespaces["csw"]} {self.parent.config.get("server", "ogc_schemas_base")}/csw/2.0.2/CSW-discovery.xsd'

        if self.parent.kvp.get('requestid'):
            etree.SubElement(node, 'csw:RequestId').text = self.parent.kvp['requestid']

        etree.SubElement(node, 'csw:SearchStatus', timestamp=timestamp)

        searchresults = etree.SubElement(node,
                                      'csw:SearchResults',
                                      numberOfRecordsMatched=matched,
                                      numberOfRecordsReturned=returned,
                                      nextRecord=nextrecord,
                                      recordSchema=self.parent.kvp['outputschema'])
        if self.parent.kvp.get('elementsetname'):
            searchresults.attrib['elementSet'] = self.parent.kvp['elementsetname']

        LOGGER.debug('Empty result set returned.')
        return node

    def _write_acknowledgement(self):
        node = etree.Element('csw:Acknowledgement',
                             nsmap=self.parent.context.namespaces,
                             version='2.0.2')
        message = etree.SubElement(node, 'csw:Message')
        message.text = 'Query was valid but not executed due to resulttype=validate'
        return node

    def exceptionreport(self, code, locator, text):
        self.parent.exception = True
        self.parent.status = 'OK'
        language = self.config.get('server', 'language', fallback='en-US')
        ogc_schemas_base = self.parent.config.get('server', 'ogc_schemas_base')
        node = etree.Element('ows:ExceptionReport', nsmap=self.parent.context.namespaces,
                            version='1.2.0', language=language)
        node.attrib[f'{{{self.parent.context.namespaces["xsi"]}}}schemaLocation'] = f'{self.parent.context.namespaces["ows"]} {ogc_schemas_base}/ows/1.0.0/owsExceptionReport.xsd'
        exception = etree.SubElement(node, 'ows:Exception', exceptionCode=code, locator=locator)
        exception_text = etree.SubElement(exception, 'ows:ExceptionText')
        exception_text.text = text
        return node

