import logging
import os
from six.moves.urllib.parse import quote, unquote
from six.moves.urllib.parse import urlparse
from six import StringIO
from six.moves.configparser import SafeConfigParser
import sys
from time import time

from pycsw.core.etree import etree
from pycsw import oaipmh, opensearch, sru
from pycsw.plugins.profiles import profile as pprofile
import pycsw.plugins.outputschemas
from pycsw.core import config, log, util
from pycsw.ogc.csw import csw2, csw3

LOGGER = logging.getLogger(__name__)

class Csw(object):
    """ Base CSW server """

    def __init__(self, config_file):
        self.config = SafeConfigParser()
        self.config.read(config_file)
        self.context = config.StaticContext(self.config)
        self.iface = csw2.Csw2(self) if self.config.get('server', 'get_mappings') == 'csw2' else csw3.Csw3(self)
        self.response = None
        self.pretty_print = self.config.getboolean('server', 'pretty_print', fallback=True)
        self.environ = {}

    def dispatch_wsgi(self):
        """ WSGI handler """
        if self.response:
            return self._write_response()

        LOGGER.debug('WSGI mode detected')
        method = self.environ['REQUEST_METHOD']

        if method == 'POST':
            content_length = int(self.environ.get('CONTENT_LENGTH', 0))
            self.request = self.environ['wsgi.input'].read(content_length)
        else:
            scheme = '%s://' % self.environ['wsgi.url_scheme']
            url = '%s%s' % (scheme, self.environ['HTTP_HOST'] or f"{self.environ['SERVER_NAME']}:{self.environ['SERVER_PORT']}")
            url += quote(self.environ.get('SCRIPT_NAME', ''))
            url += quote(self.environ.get('PATH_INFO', ''))
            if self.environ.get('QUERY_STRING'):
                url += '?' + self.environ['QUERY_STRING']
            self.request = url

            pairs = self.environ.get('QUERY_STRING', '').split('&')
            self.kvp = {pair.split('=')[0]: unquote(pair.split('=')[1]) for pair in pairs if '=' in pair}

        return self.dispatch()

    def dispatch(self):
        LOGGER.debug('Dispatching request')
        service = self.kvp.get('service', '').upper()
        version = self.kvp.get('version', '').upper()
        request = self.kvp.get('request', '').upper()
        operation = f'get{request}'
        handler = getattr(self, operation, None)

        if handler:
            return handler()

        return self.exceptionreport(code='OperationNotSupported', locator='request',
                                   text=f'{operation} is not a supported operation')

    def getrecords(self):
        """ Handle GetRecords request """
        return self.iface.getrecords()

    def _cql_update_queryables_mappings(self, cql, mappings):
        LOGGER.debug('Raw CQL text = %s', cql)
        if cql:
            for key, value in mappings.items():
                cql = cql.replace(key, value.get('dbcol', key))
            LOGGER.debug('Interpolated CQL text = %s', cql)
        return cql

    def exceptionreport(self, code, locator, text):
        self.status = 'OK'
        language = self.config.get('server', 'language', fallback='en-US')
        opengis_ows_base = self.context.ogc_schemas_base
        ogc_schemas_base = opengis_ows_base if opengis_ows_base else 'http://schemas.opengis.net/ows/'
        node = etree.Element('ows:ExceptionReport', nsmap=self.context.namespaces,
                            version='1.2.0', language=language)
        node.attrib[f'{{{self.context.namespaces["xsi"]}}}schemaLocation'] = f'{self.context.namespaces["ows"]} {ogc_schemas_base}/ows/1.0.0/owsExceptionReport.xsd'
        exception = etree.SubElement(node, 'ows:Exception', exceptionCode=code, locator=locator)
        exception_text = etree.SubElement(exception, 'ows:ExceptionText')
        exception_text.text = text
        return node

    def _write_response(self):
        response_headers = [('Content-Type', 'application/xml')]
        response_status = '200 OK'
        start_time = time()
        response_content = etree.tostring(self.response, pretty_print=self.pretty_print).decode('utf-8')
        elapsed_time = (time() - start_time) * 1000
        LOGGER.debug('Elapsed time to generate response (ms): %f', elapsed_time)
        return response_status, response_headers, [response_content]
