            return self.exceptionreport('InvalidParameterValue', param_name, f'Invalid {param_name} parameter value: {self.parent.kvp[param_name]}')

        return True

    def _process_filters_and_sorts(self):
        if any(x in ['bbox', 'q', 'time'] for x in self.parent.kvp):
            LOGGER.debug('OpenSearch Geo/Time parameters detected.')
            self.parent.kvp['constraintlanguage'] = 'FILTER'
            tmp_filter = opensearch.kvp2filterxml(self.parent.kvp, self.parent.context)
            if tmp_filter is not "":
                self.parent.kvp['constraint'] = tmp_filter
                LOGGER.debug('OpenSearch Geo/Time parameters to Filter: %s.', self.parent.kvp['constraint'])

        if 'constraint' in self.parent.kvp and self.parent.requesttype == 'GET':
            if 'constraintlanguage' not in self.parent.kvp:
                return self.exceptionreport('MissingParameterValue', 'constraintlanguage', 'constraintlanguage required when constraint specified')
            if self.parent.kvp['constraintlanguage'] not in self.parent.context.model['operations']['GetRecords']['parameters']['CONSTRAINTLANGUAGE']['values']:
                return self.exceptionreport('InvalidParameterValue', 'constraintlanguage', 'Invalid constraintlanguage: %s' % self.parent.kvp['constraintlanguage'])
            if self.parent.kvp['constraintlanguage'] == 'CQL_TEXT':
                self.parent.kvp['constraint'] = self._parse_cql_constraint()
            elif self.parent.kvp['constraintlanguage'] == 'FILTER':
                self.parent.kvp['constraint'] = self._parse_filter_constraint()

    def _parse_cql_constraint(self):
        tmp = self.parent.kvp['constraint']
        self.parent.kvp['constraint'] = {}
        self.parent.kvp['constraint']['type'] = 'cql'
        self.parent.kvp['constraint']['where'] = self.parent._cql_update_queryables_mappings(tmp, self.parent.repository.queryables['_all'])
        self.parent.kvp['constraint']['values'] = {}
        return self.parent.kvp['constraint']

    def _parse_filter_constraint(self):
        try:
            schema_path = os.path.join(self.parent.config.get('server', 'home'), 'core', 'schemas', 'ogc', 'filter', '1.1.0', 'filter.xsd')
            LOGGER.debug('Validating Filter %s.', self.parent.kvp['constraint'])
            with open(schema_path, 'rb') as schema_file:
                schema = etree.XMLSchema(file=schema_file)
            parser = etree.XMLParser(schema=schema, resolve_entities=False)
            doc = etree.fromstring(self.parent.kvp['constraint'], parser)
            LOGGER.debug('Filter is valid XML.')
            self.parent.kvp['constraint'] = {}
            self.parent.kvp['constraint']['type'] = 'filter'
            self.parent.kvp['constraint']['where'], self.parent.kvp['constraint']['values'] = fes1.parse(doc, self.parent.repository.queryables['_all'], self.parent.repository.dbtype, self.parent.context.namespaces, self.parent.orm, self.parent.language['text'], self.parent.repository.fts)
            return self.parent.kvp['constraint']
        except Exception as err:
            errortext = f'Exception: document not valid.\nError: {str(err)}'
            LOGGER.error(errortext)
            return self.exceptionreport('InvalidParameterValue', 'constraint', f'Invalid Filter query: {errortext}')

