        if 'sortby' not in self.parent.kvp:
            self.parent.kvp['sortby'] = None
        elif 'sortby' in self.parent.kvp and self.parent.requesttype == 'GET':
            try:
                name, order = self.parent.kvp['sortby'].rsplit(':', 1)
                self.parent.kvp['sortby'] = {'propertyname': self.parent.repository.queryables['_all'][name]['dbcol']}
                if name.find('BoundingBox') != -1 or name.find('Envelope') != -1:
                    self.parent.kvp['sortby']['spatial'] = True
                if order != 'A' and order != 'D':
                    return self.exceptionreport('InvalidParameterValue', 'sortby', 'Invalid SortBy value: sort order must be "A" or "D"')
                self.parent.kvp['sortby']['order'] = 'DESC' if order == 'D' else 'ASC'
