        LOGGER.debug('Querying repository with constraint: %s, sortby: %s, typenames: %s, maxrecords: %s, startposition: %s.', self.parent.kvp['constraint'], self.parent.kvp['sortby'], self.parent.kvp['typenames'], self.parent.kvp['maxrecords'], self.parent.kvp['startposition'])
        try:
            matched, results = self.parent.repository.query(
                constraint=self.parent.kvp['constraint'],
                sortby=self.parent.kvp['sortby'], typenames=self.parent.kvp['typenames'],
                maxrecords=self.parent.kvp['maxrecords'],
                startposition=int(self.parent.kvp['startposition']) - 1)
        except Exception as err:
            return self.exceptionreport('InvalidParameterValue', 'constraint', f'Invalid query: {str(err)}')

        self matched = matched
        self.results = results

    def _process_distributed_search(self):
        if (self.parent.config.has_option('server', 'federatedcatalogues') and
            'distributedsearch' in self.parent.kvp and
            self.parent.kvp['distributedsearch'] and self.parent.kvp['hopcount'] > 0):
            from owslib.csw import CatalogueServiceWeb
            from owslib.ows import ExceptionReport
            for fedcat in self.parent.config.get('server', 'federatedcatalogues').split(','):
                LOGGER.debug('Performing distributed search on federated catalogue: %s.', fedcat)
                remotecsw = CatalogueServiceWeb(fedcat, skip_caps=True)
                try:
                    remotecsw.getrecords2(xml=self.parent.request, esn=self.parent.kvp['elementsetname'], outputschema=self.parent.kvp['outputschema'])
                    if hasattr(remotecsw, 'results'):
                        LOGGER.debug('Distributed search results from catalogue %s: %s.', fedcat, remotecsw.results)
                        remotecsw_matches = int(remotecsw.results['matches'])
                        self.matched = str(int(self.matched) + remotecsw_matches)
                except ExceptionReport as err:
                    error_string = f'remote CSW {fedcat} returned exception: {err}'
                    LOGGER.error(error_string, exc_info=True)
                except Exception as err:
                    error_string = f'remote CSW {fedcat} returned error: {err}'
                    LOGGER.error(error_string, exc_info=True)

    def _construct_response(self):
        if int(self.matched) == 0:
            returned = nextrecord = '0'
        else:
            if int(self.matched) < int(self.parent.kvp['maxrecords']):
                returned = self.matched
                nextrecord = '0'
            else:
                returned = str(self.parent.kvp['maxrecords'])
                if int(self.parent.kvp['startposition']) + int(self.parent.kvp['maxrecords']) >= int(self.matched):
                    nextrecord = '0'
                else:
                    nextrecord = str(int(self.parent.kvp['startposition']) + int(self.parent.kvp['maxrecords']))

        LOGGER.debug('Results: matched: %s, returned: %s, next: %s.', self.matched, returned, nextrecord)

        node = etree.Element(util.nspath_eval('csw:GetRecordsResponse', self.parent.context.namespaces), nsmap=self.parent.context.namespaces, version='2.0.2')

        node.attrib[util.nspath_eval('xsi:schemaLocation', self.parent.context.namespaces)] = f'{self.parent.context.namespaces["csw"]} {self.parent.config.get("server", "ogc_schemas_base")}/csw/2.0.2/CSW-discovery.xsd'

        if 'requestid' in self.parent.kvp and self.parent.kvp['requestid'] is not None:
            etree.SubElement(node, util.nspath_eval('csw:RequestId', self.parent.context.namespaces)).text = self.parent.kvp['requestid']

        etree.SubElement(node, util.nspath_eval('csw:SearchStatus', self.parent.context.namespaces), timestamp=timestamp)

        if 'where' not in self.parent.kvp['constraint'] and self.parent.kvp['resulttype'] is None:
            returned = '0'

        searchresults = etree.SubElement(node, util.nspath_eval('csw:SearchResults', self.parent.context.namespaces), numberOfRecordsMatched=self.matched, numberOfRecordsReturned=returned, nextRecord=nextrecord, recordSchema=self.parent.kvp['outputschema'])

        if self.parent.kvp['elementsetname'] is not None:
            searchresults.attrib['elementSet'] = self.parent.kvp['elementsetname']

        if 'where' not in self.parent.kvp['constraint'] and self.parent.kvp['resulttype'] is None:
            LOGGER.debug('Empty result set returned.')
            return node

        if self.parent.kvp['resulttype'] == 'hits':
            return node

        if self.results is not None:
            for res in self.results:
                try:
                    if (self.parent.kvp['outputschema'] == 'http://www.opengis.net/cat/csw/2.0.2' and 'csw:Record' in self.parent.kvp['typenames']):
                        searchresults.append(self._write_record(res, self.parent.repository.queryables['_all']))
                    elif (self.parent.kvp['outputschema'] == 'http://www.opengis.net/cat/csw/2.0.2' and 'csw:Record' not in self.parent.kvp['typenames']):
                        for prof in self.parent.profiles['loaded']:
                            if self.parent.profiles['loaded'][prof].typename in self.parent.kvp['typenames']:
                                typename = self.parent.profiles['loaded'][prof].typename
                                break

                        util.transform_mappings(self.parent.repository.queryables['_all'], self.parent.context.model['typenames'][typename]['mappings']['csw:Record'], reverse=True)
                        searchresults.append(self._write_record(res, self.parent.repository.queryables['_all']))
                    elif self.parent.kvp['outputschema'] in self.parent.outputschemas.keys():
                        searchresults.append(self.parent.outputschemas[self.parent.kvp['outputschema']].write_record(res, self.parent.kvp['elementsetname'], self.parent.context, self.parent.config.get('server', 'url')))
                    else:
                        searchresults.append(self.parent.profiles['loaded'][self.parent.kvp['outputschema']].write_record(res, self.parent.kvp['elementsetname'], self.parent.kvp['outputschema'], self.parent.repository.queryables['_all']))
                except Exception as err:
                    self.parent.response = self.exceptionreport('NoApplicableCode', 'service', f'Record serialization failed: {str(err)}')
                    return self.parent.response

        if 'responsehandler' in self.parent.kvp:
            self.parent._process_responsehandler(etree.tostring(node, pretty_print=self.parent.pretty_print))
        else:
            return node

    def exceptionreport(self, code: str, locator: str, text: str) -> etree.Element:
        ''' Generate ExceptionReport '''
        self.parent.exception = True
        self.parent.status = 'OK'

        try:
            language = self.parent.config.get('server', 'language')
            ogc_schemas_base = self.parent.config.get('server', 'ogc_schemas_base')
        except:
            language = 'en-US'
            ogc_schemas_base = self.parent.context.ogc_schemas_base

        node = etree.Element(util.nspath_eval('ows:ExceptionReport', self.parent.context.namespaces), nsmap=self.parent.context.namespaces, version='1.2.0', language=language)

        node.attrib[util.nspath_eval('xsi:schemaLocation', self.parent.context.namespaces)] = f'{self.parent.context.namespaces["ows"]} {ogc_schemas_base}/ows/1.0.0/owsExceptionReport.xsd'

        exception = etree.SubElement(node, util.nspath_eval('ows:Exception', self.parent.context.namespaces), exceptionCode=code, locator=locator)

        exception_text = etree.SubElement(exception, util.nspath_eval('ows:ExceptionText', self.parent.context.namespaces))

        try:
            exception_text.text = text
        except ValueError as err:
            exception_text.text = repr(text)

        return node
