        if self.parent.kvp['elementsetname'] is not None:
            searchresults.attrib['elementSet'] = self.parent.kvp['elementsetname']

        if 'where' not in self.parent.kvp['constraint'] and self.parent.kvp['resulttype'] is None:
            LOGGER.debug('Empty result set returned.')
            return node

        if self.parent.kvp['resulttype'] == 'hits':
            return node

        if results is not None:
            LOGGER.debug('Presenting records %s - %s.', self.parent.kvp['startposition'], int(self.parent.kvp['startposition']) + (int(self.parent.kvp['maxrecords'])-1))

            for res in results:
                try:
                    if self.parent.kvp['outputschema'] == 'http://www.opengis.net/cat/csw/2.0.2' and 'csw:Record' in self.parent.kvp['typenames']:
                        searchresults.append(self._write_record(res, self.parent.repository.queryables['_all']))
                    else:
                        for prof in self.parent.profiles['loaded']:
                            if self.parent.profiles['loaded'][prof].typename in self.parent.kvp['typenames']:
                                typename = self.parent.profiles['loaded'][prof].typename
                                break
                        util.transform_mappings(self.parent.repository.queryables['_all'], self.parent.context.model['typenames'][typename]['mappings']['csw:Record'], reverse=True)
                        searchresults.append(self._write_record(res, self.parent.repository.queryables['_all']))
                except Exception as err:
                    self.parent.response = self.exceptionreport('NoApplicableCode', 'service', 'Record serialization failed: %s' % str(err))
                    return self.parent.response

        if dsresults:
            for resultset in dsresults:
                if isinstance(resultset, etree._Comment):
                    searchresults.append(resultset)
                for rec in resultset:
                    searchresults.append(etree.fromstring(resultset[rec].xml, self.parent.context.parser))

        if 'responsehandler' in self.parent.kvp:
            self.parent._process_responsehandler(etree.tostring(node, pretty_print=self.parent.pretty_print))
        else:
            return node

    def exceptionreport(self, code: str, locator: str, text: str) -> Any:
        self.parent.exception = True
        self.parent.status = 'OK'

        try:
            language = self.parent.config.get('server', 'language')
            ogc_schemas_base = self.parent.config.get('server', 'ogc_schemas_base')
        except:
            language = 'en-US'
            ogc_schemas_base = self.parent.context.ogc_schemas_base

        node = etree.Element(util.nspath_eval('ows:ExceptionReport', self.parent.context.namespaces), nsmap=self.parent.context.namespaces, version='1.2.0', language=language)
        node.attrib[util.nspath_eval('xsi:schemaLocation', self.parent.context.namespaces)] = '%s %s/ows/1.0.0/owsExceptionReport.xsd' % (self.parent.context.namespaces['ows'], ogc_schemas_base)

        exception = etree.SubElement(node, util.nspath_eval('ows:Exception', self.parent.context.namespaces), exceptionCode=code, locator=locator)
        exception_text = etree.SubElement(exception, util.nspath_eval('ows:ExceptionText', self.parent.context.namespaces))

        try:
            exception_text.text = text
        except ValueError:
            exception_text.text = repr(text)

        return node
