    def _handle_distributed_search(self) -> List[Any]:
        dsresults = []
        if self.parent.config.has_option('server', 'federatedcatalogues') and 'distributedsearch' in self.parent.kvp and self.parent.kvp['distributedsearch'] and self.parent.kvp['hopcount'] > 0:
