from time import time

from pycsw.core.etree import etree
from pycsw import oaipmh, opensearch, sru
from pycsw.plugins.profiles import profile as pprofile
import pycsw.plugins.outputschemas
from pycsw.core import config, log, util
from pycsw.ogc.csw import csw2, csw3

LOGGER = logging.getLogger(__name__)


class Csw(object):
    """ Base CSW server """

    def __init__(self, configuration: Any, context: Any, session: Any):
        self.configuration = configuration
        self.context = context
        self.session = session
        self.environ = {}
        self.request = None
        self.requesttype = None
        self.kvp = {}
        self.exception = False
        self.status = 'OK'
        self.response = None
        self.pretty_print = False
        self.orm = None
        self.language = {'text': 'en-US'}
        self.profiles = {'loaded': {}}

    def dispatch_wsgi(self) -> Any:
        if hasattr(self, 'response'):
            return self._write_response()

        LOGGER.debug('WSGI mode detected')

        if self.environ['REQUEST_METHOD'] == 'POST':
            request_body_size = int(self.environ.get('CONTENT_LENGTH', 0))
            self.requesttype = 'POST'
            self.request = self.environ['wsgi.input'].read(request_body_size)
            LOGGER.debug('Request type: POST.  Request:\n%s\n', self.request)
        else:
            self.requesttype = 'GET'
            scheme = '%s://' % self.environ['wsgi.url_scheme']
            if self.environ.get('HTTP_HOST'):
                url = '%s%s' % (scheme, self.environ['HTTP_HOST'])
            else:
                url = '%s%s' % (scheme, self.environ['SERVER_NAME'])
                if self.environ['wsgi.url_scheme'] == 'https':
                    if self.environ['SERVER_PORT'] != '443':
                        url += ':' + self.environ['SERVER_PORT']
                else:
                    if self.environ['SERVER_PORT'] != '80':
                        url += ':' + self.environ['SERVER_PORT']
            url += quote(self.environ.get('SCRIPT_NAME', ''))
            url += quote(self.environ.get('PATH_INFO', ''))
            if self.environ.get('QUERY_STRING'):
                url += '?' + self.environ['QUERY_STRING']
            self.request = url
            LOGGER.debug('Request type: GET.  Request:\n%s\n', self.request)
            pairs = self.environ.get('QUERY_STRING').split("&")
            kvp = {unquote(pair[0]): unquote(pair[1]) if len(pair) > 1 else "" for pair in [pairstr.split("=") for pairstr in pairs]}
            self.kvp = kvp

        try:
            return self.dispatch()
        except Exception as e:
            LOGGER.error(f'Error dispatching request: {e}', exc_info=True)
            return self.exceptionreport('NoApplicableCode', 'service', f'Error dispatching request: {e}')

    def getrecords(self) -> Any:
        LOGGER.debug('Handling GetRecords request')
        return csw2.Csw2(self).getrecords()

    def _cql_update_queryables_mappings(self, cql: Optional[str], mappings: Dict[str, Any]) -> str:
        LOGGER.debug(f'Raw CQL text = {cql}')
        if cql is not None:
            for key, value in mappings.items():
                cql = cql.replace(key, value['dbcol'] if isinstance(value, dict) else value)
        LOGGER.debug(f'Interpolated CQL text = {cql}')
        return cql

    def _write_response(self) -> Any:
        LOGGER.debug('Writing response')
        return self.response

    def dispatch(self) -> Any:
        # This method should be implemented to handle different operations
        LOGGER.debug('Dispatching request')
        pass

    def exceptionreport(self, code: str, locator: str, text: str) -> Any:
        self.exception = True
        self.status = 'OK'
        language = self.configuration.get('server', 'language', fallback='en-US')
        ogc_schemas_base = self.configuration.get('server', 'ogc_schemas_base', fallback=self.context.ogc_schemas_base)
        node = etree.Element(util.nspath_eval('ows:ExceptionReport', self.context.namespaces), nsmap=self.context.namespaces, version='1.2.0', language=language)
        node.attrib[util.nspath_eval('xsi:schemaLocation', self.context.namespaces)] = f'{self.context.namespaces["ows"]} {ogc_schemas_base}/ows/1.0.0/owsExceptionReport.xsd'
        exception = etree.SubElement(node, util.nspath_eval('ows:Exception', self.context.namespaces), exceptionCode=code, locator=locator)
        exception_text = etree.SubElement(exception, util.nspath_eval('ows:ExceptionText', self.context.namespaces))
        exception_text.text = text if isinstance(text, str) else repr(text)
        return node
